"""
VisionGuard AI - Alert & Threat Event Management
Original event classification, intrusion verification, and loitering analytics module.
"""

from dataclasses import dataclass, asdict
from typing import List, Dict, Tuple, Optional
import pandas as pd
from config import (
    SEVERITY_CRITICAL,
    SEVERITY_WARNING,
    SEVERITY_NORMAL,
    CLASS_CATEGORIES
)
from tracker import TrackedSubject


@dataclass
class SecurityEvent:
    """Represents a discrete security alert generated by VisionGuard AI."""
    event_id: str
    event_type: str
    timestamp_str: str
    timestamp_sec: float
    severity: str
    track_id: int
    object_class: str
    description: str
    bbox: Tuple[int, int, int, int]
    frame_idx: int

    def to_dict(self) -> Dict:
        return asdict(self)


class AlertManager:
    """
    Manages security rule evaluation, deduplication, and persistence of security events.
    Enforces restricted-zone security perimeters and loitering dwell time thresholds.
    """

    def __init__(
        self,
        restricted_zone_norm: List[float],  # [x_min, y_min, x_max, y_max] in 0.0-1.0
        loitering_threshold_sec: float = 5.0,
        intrusion_target_classes: Optional[List[str]] = None
    ):
        self.restricted_zone_norm = restricted_zone_norm
        self.loitering_threshold_sec = loitering_threshold_sec
        self.intrusion_target_classes = intrusion_target_classes or ["person"]
        
        self.events: List[SecurityEvent] = []
        self._next_event_num: int = 1
        
        # Track statistics
        self.unique_people_ids = set()
        self.unique_vehicle_ids = set()
        self.total_frame_detections: int = 0

    def format_timestamp(self, seconds: float) -> str:
        """Formats floating-point seconds into MM:SS.ss surveillance timestamp."""
        minutes = int(seconds // 60)
        secs = seconds % 60
        return f"{minutes:02d}:{secs:05.2f}"

    def get_pixel_zone(self, frame_width: int, frame_height: int) -> Tuple[int, int, int, int]:
        """Converts normalized zone coords [0.0 - 1.0] to frame pixel coordinates."""
        x1 = int(self.restricted_zone_norm[0] * frame_width)
        y1 = int(self.restricted_zone_norm[1] * frame_height)
        x2 = int(self.restricted_zone_norm[2] * frame_width)
        y2 = int(self.restricted_zone_norm[3] * frame_height)
        return (x1, y1, x2, y2)

    def is_point_in_zone(self, point: Tuple[int, int], frame_width: int, frame_height: int) -> bool:
        """Determines if a pixel coordinate lies inside the defined restricted perimeter."""
        zx1, zy1, zx2, zy2 = self.get_pixel_zone(frame_width, frame_height)
        px, py = point
        return (zx1 <= px <= zx2) and (zy1 <= py <= zy2)

    def evaluate_frame(
        self,
        active_subjects: List[TrackedSubject],
        timestamp_sec: float,
        frame_idx: int,
        frame_width: int,
        frame_height: int
    ) -> List[SecurityEvent]:
        """
        Evaluates rules against all active subjects in the frame.
        Generates Critical alerts for restricted-zone intrusions and Warning alerts for loitering.
        Guarantees no duplicate alerts for continuous events.
        """
        new_events: List[SecurityEvent] = []
        self.total_frame_detections += len(active_subjects)

        for subject in active_subjects:
            cls = subject.class_name.lower()
            category = CLASS_CATEGORIES.get(cls, "OBJECT")

            if category == "HUMAN":
                self.unique_people_ids.add(subject.track_id)
            elif category == "VEHICLE":
                self.unique_vehicle_ids.add(subject.track_id)

            # Foot / contact position estimation (bottom center of bounding box)
            bx1, by1, bx2, by2 = subject.bbox
            feet_point = (int((bx1 + bx2) / 2), by2)
            centroid_point = subject.centroid

            # Evaluate zone containment (either feet or centroid inside zone)
            in_zone = self.is_point_in_zone(feet_point, frame_width, frame_height) or \
                      self.is_point_in_zone(centroid_point, frame_width, frame_height)

            subject.is_in_zone = in_zone

            # RULE 1: Restricted Zone Intrusion (Applies to specified target classes, default: person)
            if in_zone and (cls in self.intrusion_target_classes):
                if not subject.intrusion_alert_triggered:
                    # Trigger Critical Alert once per intrusion episode
                    subject.intrusion_alert_triggered = True
                    event = self._create_event(
                        event_type="Restricted-Zone Intrusion",
                        severity=SEVERITY_CRITICAL,
                        subject=subject,
                        description=(
                            f"Restricted zone breach: {cls.capitalize()} #{subject.track_id} "
                            f"entered secure perimeter at coordinate ({feet_point[0]}, {feet_point[1]})."
                        ),
                        timestamp_sec=timestamp_sec,
                        frame_idx=frame_idx
                    )
                    new_events.append(event)
            else:
                # If subject leaves the zone, reset intrusion flag so future re-entry triggers an alert
                if not in_zone and subject.intrusion_alert_triggered:
                    subject.intrusion_alert_triggered = False

            # RULE 2: Loitering Detection (Tracked duration exceeds threshold)
            if category == "HUMAN":
                dwell_time = subject.dwell_time_seconds
                if dwell_time >= self.loitering_threshold_sec:
                    if not subject.loitering_alert_triggered:
                        # Trigger Warning Alert once per prolonged stay
                        subject.loitering_alert_triggered = True
                        event = self._create_event(
                            event_type="Loitering Detected",
                            severity=SEVERITY_WARNING,
                            subject=subject,
                            description=(
                                f"Loitering condition: Person #{subject.track_id} stationary in camera field "
                                f"for {dwell_time:.1f}s (Threshold: {self.loitering_threshold_sec:.1f}s)."
                            ),
                            timestamp_sec=timestamp_sec,
                            frame_idx=frame_idx
                        )
                        new_events.append(event)

        return new_events

    def _create_event(
        self,
        event_type: str,
        severity: str,
        subject: TrackedSubject,
        description: str,
        timestamp_sec: float,
        frame_idx: int
    ) -> SecurityEvent:
        event_id = f"EVT-{self._next_event_num:04d}"
        self._next_event_num += 1

        event = SecurityEvent(
            event_id=event_id,
            event_type=event_type,
            timestamp_str=self.format_timestamp(timestamp_sec),
            timestamp_sec=round(timestamp_sec, 2),
            severity=severity,
            track_id=subject.track_id,
            object_class=subject.class_name,
            description=description,
            bbox=subject.bbox,
            frame_idx=frame_idx
        )
        self.events.append(event)
        return event

    def get_summary_metrics(self) -> Dict:
        """Calculates comprehensive operational security statistics from real detections."""
        critical_count = sum(1 for e in self.events if e.severity == SEVERITY_CRITICAL)
        warning_count = sum(1 for e in self.events if e.severity == SEVERITY_WARNING)
        intrusion_count = sum(1 for e in self.events if e.event_type == "Restricted-Zone Intrusion")
        loitering_count = sum(1 for e in self.events if e.event_type == "Loitering Detected")

        # Derive threat level
        if critical_count > 0:
            threat_level = "CRITICAL"
        elif warning_count > 0:
            threat_level = "ELEVATED"
        else:
            threat_level = "NORMAL"

        return {
            "total_detections": self.total_frame_detections,
            "unique_people": len(self.unique_people_ids),
            "unique_vehicles": len(self.unique_vehicle_ids),
            "total_events": len(self.events),
            "critical_alerts": critical_count,
            "warning_alerts": warning_count,
            "intrusion_events": intrusion_count,
            "loitering_events": loitering_count,
            "threat_level": threat_level
        }

    def to_dataframe(self) -> pd.DataFrame:
        """Converts accumulated security events into a structured Pandas DataFrame."""
        if not self.events:
            return pd.DataFrame(columns=[
                "Event ID", "Timestamp", "Type", "Severity", "Track ID", "Class", "Description"
            ])

        records = []
        for e in self.events:
            records.append({
                "Event ID": e.event_id,
                "Timestamp": e.timestamp_str,
                "Type": e.event_type,
                "Severity": e.severity,
                "Track ID": e.track_id,
                "Class": e.object_class.capitalize(),
                "Description": e.description
            })
        return pd.DataFrame(records)

    def export_csv(self, filepath: str) -> str:
        """Saves events log to CSV file."""
        df = self.to_dataframe()
        df.to_csv(filepath, index=False)
        return filepath
